  5239	/* Eat from start of current (textual) block any reference definitions and
  5240	 * remember them so we can resolve any links referring to them.
  5241	 *
  5242	 * (Reference definitions can only be at start of it as they cannot break
  5243	 * a paragraph.)
  5244	 */
  5245	static int
  5246	md_consume_link_reference_definitions(MD_CTX* ctx)
  5247	{
  5248	    MD_LINE* lines = (MD_LINE*) (ctx->current_block + 1);
  5249	    MD_SIZE n_lines = ctx->current_block->n_lines;
  5250	    MD_SIZE n = 0;
  5251	
  5252	    /* Compute how many lines at the start of the block form one or more
  5253	     * reference definitions. */
  5254	    while(n < n_lines) {
  5255	        int n_link_ref_lines;
  5256	
  5257	        n_link_ref_lines = md_is_link_reference_definition(ctx,
  5258	                                    lines + n, n_lines - n);
  5259	        /* Not a reference definition? */
  5260	        if(n_link_ref_lines == 0)
  5261	            break;
  5262	
  5263	        /* We fail if it is the ref. def. but it could not be stored due
  5264	         * a memory allocation error. */
  5265	        if(n_link_ref_lines < 0)
  5266	            return -1;
  5267	
  5268	        n += n_link_ref_lines;
  5269	    }
  5270	
  5271	    /* If there was at least one reference definition, we need to remove
  5272	     * its lines from the block, or perhaps even the whole block. */
  5273	    if(n > 0) {
  5274	        if(n == n_lines) {
  5275	            /* Remove complete block. */
  5276	            ctx->n_block_bytes -= n * sizeof(MD_LINE);
  5277	            ctx->n_block_bytes -= sizeof(MD_BLOCK);
  5278	            ctx->current_block = NULL;
  5279	        } else {
  5280	            /* Remove just some initial lines from the block. */
  5281	            memmove(lines, lines + n, (n_lines - n) * sizeof(MD_LINE));
  5282	            ctx->current_block->n_lines -= n;
  5283	            ctx->n_block_bytes -= n * sizeof(MD_LINE);
  5284	        }
  5285	    }
  5286	
  5287	    return 0;
  5288	}
